    enunciado_final = texto + enunciado if texto else enunciado
    rows = conn.execute('''
        SELECT id FROM questoes
        WHERE escola='ITA' AND ano=2022 AND fase='1'
        AND disciplina='ingles' AND numero=?
    ''', (numero,)).fetchall()
